    {
      "i": 10,
      "speaker": "bot",
      "text": "IndiaMART सिर्फ products खरीदने बेचने का platform है।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "क्या आपको कोई product खरीदना था?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "No Madam."
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "आप अपनी future needs के लिए कभी भी IndiaMART की website visit कर सकते हैं।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "अपना समय देने के लिए धन्यवाद।"
